/// Look up `base_damage` for the card currently resolving (`player.play`'s
/// tail). The dispatch contract guarantees there is exactly one card on the
/// Play pile when a handler runs.
pub(crate) fn current_damage(state: &CombatState) -> i32 {
    sts2_core::card_effects::resolving_card_base_damage(state)
}

/// Look up `base_block` for the card currently resolving.
pub(crate) fn current_block(state: &CombatState) -> i32 {
    sts2_core::card_effects::resolving_card_base_block(state)
}

