/// Bump the per-instance `counter` on a player-owned power of the
/// given `kind` by `delta`. No-op if the power is not present.
///
/// Used by CrimsonMantle / Inferno card handlers (bead
/// `sts2-rs-6ynt.6.3`) to mirror C# `IncrementSelfDamage()` —
/// each card play increments the `self_damage` accumulator the
/// power's `after_side_turn_start` listener reads. Stacking policy
/// from bead `sts2-rs-6ynt.6.11`: re-application preserves the
/// existing instance's counter, so the bump must happen AFTER
/// `apply_power_to_player`.
pub(crate) fn increment_player_power_counter(state: &mut CombatState, kind: PowerKind, delta: i32) {
    // q6bix F-C: walk the mirror+legacy union — `apply_power_to_player`
    // (called immediately before this) routes the CrimsonMantle / Inferno
    // power onto the player's mirror Creature, so a raw `state.player.powers`
    // scan would silently no-op the counter bump in real combat.
    let Some(uid) = state
        .player_power_uids()
        .into_iter()
        .find(|uid| state.powers.iter().any(|p| p.id == uid.0 && p.kind == kind))
    else {
        return;
    };
    if let Some(pow) = state.powers.get_mut_by_id(uid.0) {
        pow.counter = pow.counter.saturating_add(delta);
    }
}

/// Apply `amount` stacks of `kind` to the player (self). No-op if amount <= 0.
///
/// Bead `sts2-rs-au4l2` (d03 split-brain fix): when the player's mirror
/// `creature_uid` is set, route through
/// [`sts2_core::card_effects::apply_power_to_creature`] so card-applied
/// self-powers stack onto the SAME instance as relic combat-start grants
/// (which already land on `state.creatures[uid].powers`). Without this,
/// VAJRA's +1 Strength (creature-side) and Inflame's +2 Strength
/// (legacy `state.player.powers`) live as two separate `Strength`
/// instances. Falls back to the legacy push when the mirror is unset
/// (smoke tests / pre-d03 fixtures).
pub(crate) fn apply_power_to_player(state: &mut CombatState, kind: PowerKind, amount: i32) {
    if amount <= 0 {
        return;
    }
    if let Some(uid) = state.player.creature_uid {
        sts2_core::card_effects::apply_power_to_creature(state, uid, kind, amount);
        return;
    }
    // Legacy path (no mirror creature): stack into existing instance if present.
    let existing_uid = state
        .player
        .powers
        .iter()
        .copied()
        .find(|uid| state.powers.iter().any(|p| p.id == uid.0 && p.kind == kind));
    if let Some(uid) = existing_uid {
        if let Some(pow) = state.powers.get_mut_by_id(uid.0) {
            pow.amount = pow.amount.saturating_add(amount);
        }
        return;
    }
    let next_id_raw = state
        .powers
        .iter()
        .map(|p| p.id.get())
        .max()
        .map_or(1, |m| m.saturating_add(1));
    let new_id = NonZeroU32::new(next_id_raw).expect("power id non-zero");
    state.powers.push(Power {
        id: new_id,
        kind,
        amount,
        counter: 0,
        applier: None,
        skip_next_tick: false,
    });
    state.player.powers.push(PowerUid(new_id));
}

/// Mid-card self HP loss (unblockable, unpowered, skip-hurt). Mirrors
/// Python `_self_hp_loss(card, combat, amount)` in
/// `sts2-rl-agent@01c094d:sts2_env/cards/ironclad.py:62-69` which calls
/// `apply_damage(owner, amount, ValueProp.UNBLOCKABLE | UNPOWERED |
/// SKIP_HURT_ANIM, combat, owner)`. The Rust port routes through
/// [`sts2_core::combat_loop::apply_damage_to_player`] (which is the
/// canonical player-target damage helper at this pin and runs the same
/// pipeline as `apply_damage` for enemies — see the `apply_damage_to_player`
/// doc-comment for the why).
///
/// `SKIP_HURT_ANIM` has no Rust counterpart (we don't render); the other
/// two flags suffice for byte-equivalent listener firing — Rupture /
/// Pyre / `DemonForm` install themselves as `after_damage_received`
/// listeners on the player and trigger off this path.
///
/// Bead `sts2-rs-hdy` (G3 plumbing). Guarded against `amount <= 0` so
/// upgraded-card variants that zero out the HP-loss are no-ops.
pub(crate) fn self_hp_loss(state: &mut CombatState, amount: i32) {
    if amount <= 0 {
        return;
    }
    // The smoke fixture (`fresh_state_with_enemy`) leaves player HP at
    // the default (0). Guarding here keeps `every_card_dispatches_without_panic`
    // green without changing live-combat semantics — `apply_damage_to_player`
    // is a no-op-then-return-CombatLost on an already-dead player anyway.
    if state.player.current_hp <= 0 {
        return;
    }
    let _ = sts2_core::combat_loop::apply_damage_to_player(
        state,
        CreatureRef::Player,
        amount,
        ValueProps::UNBLOCKABLE.union(ValueProps::UNPOWERED),
        None,
    );
}

/// Hit every alive enemy for `dmg` damage. The `combat_loop` currently
/// short-circuits `AllEnemies` targeting before dispatch, so this is only
/// invoked from compound handlers (Whirlwind, etc.) that synthesise the
/// `AllEnemies` fan-out from inside an Enemy-targeted shell.
pub(crate) fn deal_damage_all_enemies(state: &mut CombatState, dmg: i32) {
    // Delegate to the canonical core fan-out so this AoE matches C#
    // `CreatureCmd.Damage(AllEnemies)`: every target's `ModifyDamage` is
    // resolved against the constant pre-death dealer state before the single
    // post-loop `Kill`, so a mid-AoE death (Shrink removal / Possess give-back)
    // can't retroactively change a surviving target's hit. Threads the same
    // originating card the single-target helper derives internally. Bead
    // `sts2-rs-8gzvn`.
    let card = sts2_core::card_effects::originating_card_id(state);
    let _ = sts2_core::card_effects::deal_damage_to_all_alive_enemies(
        state,
        dmg,
        sts2_core::hooks::ValueProps::MOVE,
        card,
    );
}

/// Read the `Vulnerable` stack on an enemy creature (0 if absent). Used by
/// Bully (damage scales with target Vulnerable) and Dominate (Strength gain).
pub(crate) fn enemy_vulnerable(state: &CombatState, target: CreatureUid) -> i32 {
    state
        .creatures
        .iter()
        .find(|c| c.id == target.0)
        .map(|c| c.powers.clone())
        .unwrap_or_default()
        .iter()
        .find_map(|pu| {
            state
                .powers
                .iter()
                .find(|p| p.id == pu.0 && p.kind == PowerKind::Vulnerable)
                .map(|p| p.amount)
        })
        .unwrap_or(0)
}

/// Exhaust the first hand card (`uid`), firing `after_card_exhausted` on both
/// the power-arena and relic buses so exhaust synergies (Dark Embrace, Feel No
/// Pain, …) tick. Mirrors the inline `CardCmd.Exhaust` path in
/// [`sts2_core::combat_loop`]; used by FiendFire / Thrash which exhaust
/// hand cards mid-play. No-op if `uid` is not in hand.
pub(crate) fn exhaust_hand_card(state: &mut CombatState, uid: sts2_core::CardUid) {
    if !state.player.hand.contains(&uid) || !sts2_core::combat_loop::exhaust_may_begin(state) {
        return;
    }
    let idx = uid.0.get() as usize - 1;
    let card = &state.cards[idx];
    let card_id = card.card_id;
    let card_type = card.card_type;
    let card_tags = card.tags;
    let _ = sts2_core::cards::move_card(
        &mut state.player,
        uid,
        sts2_core::cards::PileKind::Hand,
        sts2_core::cards::PileKind::Exhaust,
    );
    let exhaust_ctx = sts2_core::relic_effects::CardEventCtx {
        card_id,
        card_uid: Some(uid),
        target: None,
        card_tags,
        energy_spent: 0,
    };
    let _ = sts2_core::relic_effects::dispatch_after_card_exhausted(state, &exhaust_ctx);
    let hook_ctx = sts2_core::hooks::CardCtx {
        card_id: Some(card_id),
        card_uid: Some(uid),
        card_tags,
        card_type: Some(card_type),
    };
    // Mid-play hand-card exhaust (FiendFire / Thrash) — not the
    // end-of-turn ethereal sweep, so `caused_by_ethereal = false`. Bead
    // `sts2-rs-umouk`.
    sts2_core::hooks::dispatch_after_card_exhausted(state, &hook_ctx, false);
}

/// Build a [`sts2_core::PendingChoice`] option list covering every card
/// currently in the player's hand (no filter — mirrors C#
/// `CardSelectCmd.FromHand(filter: null)`). Used by the Brand /
/// BurningPact "select 1 card to Exhaust" prompts. Bead `sts2-rs-pe5zo`.
pub(crate) fn hand_exhaust_options(state: &CombatState) -> Vec<sts2_core::ChoiceOption> {
    state
        .player
        .hand
        .iter()
        .map(|uid| {
            let idx = uid.0.get() as usize - 1;
            let card_id = state
                .cards
                .get(idx)
                .map_or(sts2_core::cards::CardId::StrikeIronclad, |c| c.card_id);
            let upgraded = state.cards.get(idx).is_some_and(|c| c.upgraded);
            sts2_core::ChoiceOption {
                card_id,
                upgraded,
                card_uid: Some(*uid),
                source_pile: Some(sts2_core::cards::PileKind::Hand),
            }
        })
        .collect()
}

/// Signed-amount power application (mirrors `colorless.rs` /
/// `silent.rs::apply_power_signed_to_creature`). The shared
/// `apply_power_to_enemy` early-outs on `amount <= 0`, so the temporary
/// `-Strength` debuff legs (Mangle's `BeforeApplied`) route through this
/// direct-arena push. Bead `sts2-rs-q6bix` (F-K).
pub(crate) fn apply_power_signed_to_creature(
    state: &mut CombatState,
    target_uid: CreatureUid,
    kind: PowerKind,
    amount: i32,
) {
    if amount == 0 {
        return;
    }
    // C# `ArtifactPower` negates a Debuff-direction application (a negative
    // attribute drain) and consumes a stack; the canonical affliction gate
    // misses signed drains, so consult the signed-debuff gate (no-op for
    // positive restores).
    if amount < 0
        && sts2_core::card_effects::try_consume_artifact_for_signed_debuff(
            state, target_uid, amount,
        )
    {
        return;
    }
    let Some(creature_idx) = state
        .creatures
        .iter()
        .position(|c| c.id == target_uid.0 && c.current_hp > 0)
    else {
        return;
    };
    let existing_uid = state.creatures[creature_idx]
        .powers
        .iter()
        .copied()
        .find(|uid| state.powers.iter().any(|p| p.id == uid.0 && p.kind == kind));
    if let Some(uid) = existing_uid {
        let now_zero = if let Some(pow) = state.powers.get_mut_by_id(uid.0) {
            pow.amount = pow.amount.saturating_add(amount);
            pow.amount == 0
        } else {
            false
        };
        if now_zero {
            // C# `PowerCmd.Apply` removes an additive power when its amount
            // reaches exactly 0 (StrengthPower has no `CanBeZero` override) —
            // a negative result keeps the power. Mangle reducing a STRENGTH(10)
            // enemy by -10 must leave `[MANGLE]`, not `[MANGLE, STRENGTH(0)]`
            // (sweep seed 2937, bead `sts2-rs-uknxs`). Mirror the
            // `damage.rs` dead-applier teardown removal shape.
            let pid = uid.0;
            state.powers.retain(|p| p.id != pid);
            state.creatures[creature_idx].powers.retain(|u| u.0 != pid);
        }
        return;
    }
    let next_id_raw = state
        .powers
        .iter()
        .map(|p| p.id.get())
        .max()
        .map_or(1, |m| m.saturating_add(1));
    let new_id = NonZeroU32::new(next_id_raw).expect("power id non-zero");
    state.powers.push(sts2_core::Power {
        id: new_id,
        kind,
        amount,
        counter: 0,
        applier: None,
        skip_next_tick: false,
    });
    state.creatures[creature_idx]
        .powers
        .push(sts2_core::PowerUid(new_id));
}
